from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

with open('mono_debug.so', 'rb') as f:
    elf = ELFFile(f)
    dwarf = elf.get_dwarf_info()

    targets = {0x2f4b20, 0x2f4c84, 0x16de04}

    for cu in dwarf.iter_CUs():
        lp = dwarf.line_program_for_CU(cu)
        if lp is None:
            continue

        entries = lp.get_entries()
        prev = None
        for entry in entries:
            state = entry.state
            if state is None:
                continue
            for t in targets:
                if prev and prev.address <= t < state.address:
                    fname = lp['file_entry'][prev.file - 1].name
                    if isinstance(fname, bytes):
                        fname = fname.decode()
                    print(f'0x{t:x} -> {fname}:{prev.line}')
            prev = state
            if state.end_sequence:
                prev = None
" 2>&1

