from elftools.elf.elffile import ELFFile
from capstone import *

with open('mono_debug.so', 'rb') as f:
    elf = ELFFile(f)

    # Find the section containing our addresses
    for section in elf.iter_sections():
        if section['sh_addr'] <= 0x2f4b20 < section['sh_addr'] + section['sh_size']:
            print(f'Section: {section.name} at 0x{section[\"sh_addr\"]:x}')
            break

    md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)

    for addr in [0x2f4b20, 0x2f4c84]:
        # Read a few instructions at the address
        for section in elf.iter_sections():
            if section['sh_addr'] <= addr < section['sh_addr'] + section['sh_size']:
                offset = addr - section['sh_addr']
                data = section.data()[offset:offset+16]
                print(f'\n0x{addr:x}:')
                for insn in md.disasm(data, addr):
                    print(f'  0x{insn.address:x}: {insn.mnemonic} {insn.op_str}')
                break
" 2>&1", "description": "Disassemble thunk targets"}

