from elftools.elf.elffile import ELFFile
from capstone import *

with open('mono_binary.so', 'rb') as f:
    elf = ELFFile(f)
    for addr in [0x16de04]:
        for section in elf.iter_sections():
            if section['sh_addr'] <= addr < section['sh_addr'] + section['sh_size']:
                print(f'0x{addr:x} in section {section.name}')
                break

    # Also find .dynsym entries for those SGen addresses
    dynsym = elf.get_section_by_name('.dynsym')
    if dynsym:
        import bisect
        funcs = [(s['st_value'], s['st_size'], s.name) for s in dynsym.iter_symbols() if s['st_info']['type'] == 'STT_FUNC' and s['st_value'] > 0]
        funcs.sort()
        addrs_list = [f[0] for f in funcs]
        for addr in [0x2f4b20, 0x2f4c84, 0x2c1a40]:
            idx = bisect.bisect_right(addrs_list, addr) - 1
            if idx >= 0:
                base, size, name = funcs[idx]
                print(f'0x{addr:x} -> dynsym: {name}+0x{addr-base:x} (0x{base:x}, size=0x{size:x})')
" 2>&1", "description": "Verify sections and dynsym"}

